inherit(Object, #StepBudgetAdvisor, #(), 0, nil)!!

now(StepBudgetAdvisor)!!

Def remainingBudget(self, h | m c r) {
    m := maxSteps(h);
    if (m <= 0) then ^ -1; endif;
    c := stepCount(h);
    r := m - c;
    if (r < 0) then r := 0; endif;
    ^ r;
}!!

inherit(Object, #StepBudgetAdvisor, #(), 0, nil)!!

now(StepBudgetAdvisor)!!

Def consecutiveErrors(self, h | log n i e st cnt) {
    log := stepLog(h);
    n := size(log);
    cnt := 0;
    i := n - 1;
    loop while (i >= 0) begin
        e := log[i];
        st := at(e, #status);
        if (st == "error") then
            cnt := cnt + 1;
        else
            i := -1;
        endif;
        i := i - 1;
    endLoop;
    ^ cnt;
}!!

